	ZNode findZNodeAt(Point p) {
		ZNode found = null;
		synchronized (zNodes) {
			for (ZNode z : zNodes) {
				final double hs = z.getSize() * scale * 0.5;
				if (translateToDisplayPoint(z.getLocation()).distance(p.x, p.y) < hs) {
					found = z;
				}
			}
		}
		return found;
	}

