		// get status
		int status = httpResponse.getStatusLine().getStatusCode();

		InputStream content = null;
		String response = "";

		// Get the response Entity
		HttpEntity entity = httpResponse.getEntity();
		if (entity != null) {
			content = entity.getContent();
			if (content != null) {
				response = readStream(content);
			}
