	private static String getFormattedContentTypeString(ContentType contentTypeFormat) {

		switch (contentTypeFormat) {
		case WWW_FORM:
			return WWW_FORM_URLENCODED_CONTENT_TYPE;
		case JSON:
			return JSON_CONTENT_TYPE;
		default:
			return WWW_FORM_URLENCODED_CONTENT_TYPE;
		}
	}

